// Contract: JobSpy record (fixtures generated by JobSpy's own serializer) ->
// adapter -> CanonicalJob.
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { canonicalJobSchema } from "@applypilot/job-schema";
import { mapJobSpyEnvelope, mapJobSpyRecord, type JobSpyEnvelope } from "../src/index.ts";

const fixtures = resolve(dirname(fileURLToPath(import.meta.url)), "../../../tests/fixtures/jobspy");
const load = (site: string): Record<string, unknown>[] =>
  JSON.parse(readFileSync(join(fixtures, `${site}.json`), "utf8"));
const ctx = {
  runId: "run_fixture",
  discoveredAt: "2026-11-15T12:00:00.000Z",
  upstreamVersion: "python-jobspy@1.4.1",
};

const expectedSource: Record<string, string> = {
  linkedin: "linkedin",
  indeed: "indeed",
  glassdoor: "glassdoor",
  zip_recruiter: "ziprecruiter",
  google: "google",
  naukri: "other",
  bayt: "other",
  bdjobs: "other",
  hellowork: "other",
};

test("every supported JobSpy board has a fixture", () => {
  const sites = readdirSync(fixtures)
    .filter((f) => f.endsWith(".json"))
    .map((f) => f.replace(/\.json$/, ""))
    .sort();
  assert.deepEqual(sites, Object.keys(expectedSource).sort());
});

for (const site of Object.keys(expectedSource)) {
  test(`${site}: every fixture row maps to a valid CanonicalJob with provenance`, () => {
    const rows = load(site);
    assert.ok(rows.length > 0);
    for (const row of rows) {
      const { job, warnings } = mapJobSpyRecord(row, ctx);
      assert.deepEqual(warnings, []);
      canonicalJobSchema.parse(job);
      assert.equal(job.source, expectedSource[site]);
      assert.equal(job.sourceUrl, row.job_url);
      assert.equal(job.externalId, row.id);
      assert.equal(job.title, row.title);
      assert.equal(job.company, row.company);
      assert.equal(job.provenance[0]?.site, site);
      assert.equal(job.provenance[0]?.adapter, "jobspy");
      assert.equal(job.provenance[0]?.upstreamVersion, "python-jobspy@1.4.1");
      assert.deepEqual(job.rawSource, row, "raw upstream record is preserved verbatim");
    }
  });
}

test("field mapping is pinned for a fully populated record", () => {
  const [row] = load("indeed");
  const { job } = mapJobSpyRecord(row, ctx);
  const { rawSource: _raw, description, ...rest } = job;
  assert.match(description ?? "", /RAG pipelines/);
  assert.deepEqual(rest, {
    id: rest.id,
    externalId: "in-5e409e577046abcd",
    title: "GenAI Engineer",
    company: "Contoso Analytics",
    location: "Austin, TX, USA",
    remoteType: "unknown",
    source: "indeed",
    sourceUrl: "https://www.indeed.com/viewjob?jk=5e409e577046abcd",
    postedAt: "2026-11-12",
    salaryMin: 140000,
    salaryMax: 180000,
    salaryCurrency: "USD",
    salaryInterval: "yearly",
    employmentType: "fulltime, contract",
    discoveredAt: ctx.discoveredAt,
    provenance: [
      {
        provider: "indeed",
        site: "indeed",
        url: "https://www.indeed.com/viewjob?jk=5e409e577046abcd",
        applyUrl: "https://careers.contoso.example/jobs/123",
        externalId: "in-5e409e577046abcd",
        adapter: "jobspy",
        upstreamVersion: "python-jobspy@1.4.1",
        runId: "run_fixture",
        discoveredAt: ctx.discoveredAt,
      },
    ],
  });
});

test("remote type comes only from explicit signals", () => {
  const [onsiteLooking, remote] = load("linkedin");
  assert.equal(mapJobSpyRecord(onsiteLooking, ctx).job.remoteType, "unknown");
  assert.equal(mapJobSpyRecord(remote, ctx).job.remoteType, "remote");
  assert.equal(mapJobSpyRecord(load("naukri")[0], ctx).job.remoteType, "hybrid");
  assert.equal(mapJobSpyRecord(load("glassdoor")[0], ctx).job.remoteType, "remote");
});

test("hourly pay keeps its native interval instead of being annualised", () => {
  const { job } = mapJobSpyRecord(load("glassdoor")[0], ctx);
  assert.deepEqual([job.salaryMin, job.salaryMax, job.salaryInterval], [70, 85, "hourly"]);
});

test("ids are stable across runs and differ across boards", () => {
  const [row] = load("linkedin");
  const a = mapJobSpyRecord(row, ctx).job.id;
  const b = mapJobSpyRecord(row, { ...ctx, runId: "run_other", discoveredAt: "2026-11-16T00:00:00Z" }).job.id;
  assert.equal(a, b);
  assert.notEqual(a, mapJobSpyRecord({ ...row, site: "indeed" }, ctx).job.id);
});

test("bad rows are rejected with a reason, and suspicious values produce warnings", () => {
  const [row] = load("indeed");
  assert.throws(() => mapJobSpyRecord({ ...row, company: " " }, ctx), /company is missing/);
  assert.throws(() => mapJobSpyRecord({ ...row, job_url: "javascript:alert(1)" }, ctx), /http\(s\) URL/);
  assert.throws(() => mapJobSpyRecord({ site: "indeed" }, ctx), /not a JobSpy record/);
  const inverted = mapJobSpyRecord({ ...row, min_amount: 200000, max_amount: 100000 }, ctx);
  assert.equal(inverted.job.salaryMin, undefined);
  assert.match(inverted.warnings[0] ?? "", /salary dropped/);
});

function envelope(records: unknown[], bySite: JobSpyEnvelope["metrics"]["by_site"]): JobSpyEnvelope {
  return {
    version: "applypilot.jobspy.result@1",
    run_id: "run_env",
    started_at: "2026-11-15T12:00:00.000Z",
    finished_at: "2026-11-15T12:00:05.000Z",
    duration_ms: 5000,
    upstream: { package: "python-jobspy", version: "1.4.1" },
    request: { site_name: Object.keys(bySite) },
    metrics: { requested_per_site: 15, returned: records.length, by_site: bySite },
    records,
    error: null,
  };
}

test("an envelope maps every record, counts per board and never drops one silently", () => {
  const linkedin = load("linkedin");
  const indeed = load("indeed");
  const broken = { ...indeed[0], id: "in-broken", company: "" };
  const result = mapJobSpyEnvelope(
    envelope([...linkedin, ...indeed, broken, linkedin[0]], {
      linkedin: { returned: 3, error: null, warnings: [] },
      indeed: { returned: 2, error: null, warnings: ["easy_apply ignored"] },
      glassdoor: { returned: 0, error: "response status code 403", warnings: [] },
    }),
  );
  assert.equal(result.status, "partial");
  assert.equal(result.metrics.returned, 5);
  assert.equal(result.metrics.mapped, 3);
  assert.equal(result.metrics.rejected, 1);
  assert.equal(result.metrics.duplicates, 1);
  assert.equal(result.metrics.mapped + result.metrics.rejected + result.metrics.duplicates, 5);
  assert.equal(result.metrics.bySite.indeed?.rejected, 1);
  assert.deepEqual(result.errors, [{ site: "glassdoor", message: "response status code 403" }]);
  assert.match(result.rejected[0]?.reason ?? "", /company is missing/);
  assert.equal(result.jobs[0]?.discoveredAt, "2026-11-15T12:00:05.000Z");
});

test("a run where every board failed has status failed", () => {
  const result = mapJobSpyEnvelope(
    envelope([], { linkedin: { returned: 0, error: "429", warnings: [] } }),
  );
  assert.equal(result.status, "failed");
});
